def compute(vars):
    previous = vars["v2"]
    current = vars["v1"]
    if previous == 0:
        return None
    change = current - previous
    percentage_change = (change / previous) * 100
    return {
        "value": percentage_change,
        "trace": {
            "previous_total_assets": previous,
            "current_total_assets": current,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
